const payload = $input.first().json;
const data = payload.data || payload;
const amount = parseFloat(data.amount || 0);
const expected = parseFloat(data.expected || 0);
const description = data.description || 'Expense';
const severity = data.severity || (amount > 20000 ? 'high' : 'medium');
const zScore = data.zScore || (severity === 'high' ? 3.5 : 2.2);
const userId = payload.userId || data.userId;
const txId = payload.referenceId || data.transactionId;

// Generate plain-English explanation
const ratio = expected > 0 ? (amount / expected).toFixed(1) : '3x';
const explanation = `Spending of ₹${amount.toLocaleString()} is ${ratio} times higher than your usual average of ₹${expected.toLocaleString()}.`;

return [{
  json: {
    userId,
    transactionId: txId,
    description,
    amount,
    expected,
    severity,
    zScore,
    explanation,
    requiresHold: severity === 'high',
    logId: payload.logId,
    timestamp: new Date().toISOString()
  }
}];
